import { Arena } from "/js/snippet/arena.json"
const MAIN_CHANNEL = "recipe-journals"

function arena() {
  // ----------------------------
  // Initialize Are.na
  // ----------------------------
  let init_arena = () => {
    // attempt auth
    client = Arena({auth: auth()})
    client.me().then((res) => {
      if (res.slug) { logged_as.set(res.slug) }
    })
  }

  // -----------------------------
  // Login DOM
  // -----------------------------
  let login = () => {
    let input = sig("")
    let oninput = (e) => auth.set(e.target.value)
    let save = () => {
      auth.set(input())
      localStorage.setItem("AUTH", auth()) 
      init_arena()
    }
    return html`
      input [type="text" oninput=${oninput}] 
      button [onclick=${save}] -- save
    `
  }

  let logger = mem(() => {
    if (!auth()){
      return login()
      console.log("no auth")
    } else {
      init_arena()
      return html`span.auth -- authenticated as: ${logged_as}`
    }
  })
  let ing_block = block => {
    const first_line = (str) => str.split(`\n`).shift()
    return html`
    div.block [onclick=${() => {
      selected_block.set(block) 
    }}
    style=cursor:pointer
    ]
      p -- ${first_line(block.content)}
    `
  }

  return html`
    h1 -- Arena
    .login -- ${logger}
    .ingredients
      h4 -- Ingredients
      each of ${ingredients} as ${ing_block}

      h4 -- Dishes
      each of ${dishes} as ${ing_block}
  `
}

